/**
 * Writes the iOS app icon and launch-screen logo from the Android launcher icon sources (assets/).
 * They're build outputs: gitignored, regenerated by `npm run ios`. Android is not touched.
 *   npx tsx scripts/icon.ts
 */
import { rmSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { launchLogo, squareIcon } from './lib/icons.ts';

const xcassets = join(import.meta.dirname, '../ios/App/App/Assets.xcassets');
const iconDir = join(xcassets, 'AppIcon.appiconset');
const splashDir = join(xcassets, 'Splash.imageset');

// Drop any other PNGs (e.g. Capacitor's placeholder images) so only ours are in the catalog.
for (const dir of [iconDir, splashDir]) {
  for (const f of readdirSync(dir)) if (f.endsWith('.png')) rmSync(join(dir, f));
}

// App icon: one opaque 1024×1024 square; iOS rounds the corners itself.
writeFileSync(join(iconDir, 'AppIcon-1024.png'), await squareIcon(1024));
// Launch logo: shown at 160pt in the centre of the launch screen (LaunchScreen.storyboard), @3x.
writeFileSync(join(splashDir, 'splash-logo@3x.png'), await launchLogo(480));

console.log('iOS app icon + launch logo written');
